window.ScripturaLexicons.THAYER.rowsHtml+="<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0009\" data-source=\"THAYER\" data-search=\"Ἀβιληνή substantivo feminino; nome geográfico Abilene, região ao norte de Damasco Lc 3.1 Thayer página 2\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀβιληνή</td><td>substantivo feminino; nome geográfico</td><td>Abilene, região ao norte de Damasco</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0010\" data-source=\"THAYER\" data-search=\"Ἀβιούδ nome próprio masculino, indeclinável Abiúde, filho de Zorobabel Mt 1.13 Thayer página 2\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀβιούδ</td><td>nome próprio masculino, indeclinável</td><td>Abiúde, filho de Zorobabel</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0011\" data-source=\"THAYER\" data-search=\"Ἀβραάμ nome próprio masculino Abraão, patriarca de Israel e paradigma de fé Gn 17.5; Mt 1.1; 22.32; Lc 19.9; Jo 8.33; At 3.25; Hb 7.1 ss.; 11.8; Rm 4.1 ss.,17 ss.; Gl 3.6–7,29 Thayer página 2\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀβραάμ</td><td>nome próprio masculino</td><td>Abraão, patriarca de Israel e paradigma de fé</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0012\" data-source=\"THAYER\" data-search=\"ἄβυσσος adjetivo e substantivo feminino sem fundo; abismo; profundezas, morada dos mortos ou demônios Sb 10.19; Gn 1.2; 7.11; Dt 8.7; Eclo 1.3; 16.18; Sl 70(71).21; Rm 10.7; Lc 8.31; Ap 9.1–2,11; 11.7; 17.8; 20.1,3 Thayer página 2\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄβυσσος</td><td>adjetivo e substantivo feminino</td><td>sem fundo; abismo; profundezas, morada dos mortos ou demônios</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0013\" data-source=\"THAYER\" data-search=\"Ἅγαβος nome próprio masculino Ágabo, profeta cristão At 11.28; 21.10 Thayer página 2\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἅγαβος</td><td>nome próprio masculino</td><td>Ágabo, profeta cristão</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0014\" data-source=\"THAYER\" data-search=\"ἀγαθοεργέω verbo praticar o bem; ser beneficente 1Tm 6.18 Thayer página 2\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγαθοεργέω</td><td>verbo</td><td>praticar o bem; ser beneficente</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0015\" data-source=\"THAYER\" data-search=\"ἀγαθοποιέω verbo fazer o bem; beneficiar alguém; agir corretamente Mc 3.4; Lc 6.9,33,35; At 14.17 (TR); 1Pe 2.15,20; 3.6,17; 3Jo 11; Sf 1.12; Nm 10.32; Tb 12.13 Thayer página 2\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγαθοποιέω</td><td>verbo</td><td>fazer o bem; beneficiar alguém; agir corretamente</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0016\" data-source=\"THAYER\" data-search=\"ἀγαθοποιΐα substantivo feminino prática do bem; conduta correta 1Pe 4.19; Testamento de José §18 Thayer página 2\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγαθοποιΐα</td><td>substantivo feminino</td><td>prática do bem; conduta correta</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0017\" data-source=\"THAYER\" data-search=\"ἀγαθοποιός adjetivo de duas terminações aquele que pratica o bem; que age corretamente 1Pe 2.14; Eclo 42.14; Plutarco, De Iside et Osiride §42 Thayer página 2\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγαθοποιός</td><td>adjetivo de duas terminações</td><td>aquele que pratica o bem; que age corretamente</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n";
window.ScripturaLexicons.THAYER.cardsHtml+="<article id=\"entry-thayer-0009\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"2\" data-thayer-pdf-leaf=\"26\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἀβιληνή\" data-meanings=\"Abilene, região ao norte de Damasco\">Ἀβιληνή</h1><div class=\"entry-meta\">substantivo feminino; nome geográfico · Thayer, p. impressa 2, coluna esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução do artigo impresso</div><p class=\"entry-text\">Ἀβιληνή, -ης, ἡ: Abilene, nome de um território associado à cidade de Ábila, situado entre o Líbano e o Hermom, na direção da Fenícia; a dezoito milhas de Damasco e trinta e sete de Heliópolis (trinta e oito segundo o Itinerário de Antonino). Lucas 3.1. Compare o artigo Λυσανίας e o Bible Dictionary citado por Thayer.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Lc 3.1</p></section><section class=\"entry-section\"><div class=\"section-title\">Texto inglês extraído da fotografia (OCR não canônico)</div><p class=\"entry-text\" style=\"white-space:pre-wrap\">&quot;ABAnvy [WH ‘ABerd. (see 8. v. et], -7s, 7, (SC. xopa, \nthe district belonging to the city Abila), Abilene, the \nname of a region lying between Lebanon and Hermon \ntowards Phoenicia, 18 miles distant from Damascus and \n37 [acc. to the Itin. Anton. 38] from Heliopolis: Lk. iii. \n1. Cf. Avoavias [and B. D. s. v.].*</p></section><section class=\"entry-section\"><div class=\"section-title\">Fonte</div><p class=\"entry-text\">Thayer, fac-símile, página impressa 2, folha PDF 26, coluna esquerda. Em caso de diferença, prevalece a fotografia, não a transcrição OCR.</p></section></article>\n<article id=\"entry-thayer-0010\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"2\" data-thayer-pdf-leaf=\"26\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἀβιούδ\" data-meanings=\"Abiúde, filho de Zorobabel\">Ἀβιούδ</h1><div class=\"entry-meta\">nome próprio masculino, indeclinável · Thayer, p. impressa 2, coluna esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução do artigo impresso</div><p class=\"entry-text\">Ἀβιούδ, nome próprio indeclinável, relacionado ao hebraico que Thayer interpreta «pai dos judeus» (ou, segundo outra explicação, «pai de glória»). Abiúde, filho de Zorobabel: Mateus 1.13.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Mt 1.13</p></section><section class=\"entry-section\"><div class=\"section-title\">Texto inglês extraído da fotografia (OCR não canônico)</div><p class=\"entry-text\" style=\"white-space:pre-wrap\">*ABiovs, 5, indecl. prop. name, T3138 (father of the \nJews (al. of glory]), Abiud, son of Zorobabel or Zerub￾babel: Mt. i. 13.*</p></section><section class=\"entry-section\"><div class=\"section-title\">Fonte</div><p class=\"entry-text\">Thayer, fac-símile, página impressa 2, folha PDF 26, coluna esquerda. Em caso de diferença, prevalece a fotografia, não a transcrição OCR.</p></section></article>\n<article id=\"entry-thayer-0011\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"2\" data-thayer-pdf-leaf=\"26\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἀβραάμ\" data-meanings=\"Abraão, patriarca de Israel e paradigma de fé\">Ἀβραάμ</h1><div class=\"entry-meta\">nome próprio masculino · Thayer, p. impressa 2, coluna esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução do artigo impresso</div><p class=\"entry-text\">Ἀβραάμ: Abraão; o verbete registra forma alternativa de tradição textual e uma forma declinável empregada por Josefo. Correspondente ao hebraico אַבְרָהָם, «pai de multidão», conforme Gênesis 17.5. Patriarca célebre e fundador da nação judaica: Mateus 1.1 ss.; 22.32; Lucas 19.9; João 8.33; Atos 3.25; Hebreus 7.1 ss. e muitas outras passagens.</p>\n<p class=\"entry-text\">Paulo o exalta como modelo da fé em Romanos 4.1 ss. e 4.17 ss. e Gálatas 3.6 (compare Hebreus 11.8). Em razão disso, todos os crentes em Cristo podem ser chamados filhos ou descendência de Abraão (Gálatas 3.7,29; compare Romanos 4.11).</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Gn 17.5; Mt 1.1; 22.32; Lc 19.9; Jo 8.33; At 3.25; Hb 7.1 ss.; 11.8; Rm 4.1 ss.,17 ss.; Gl 3.6–7,29</p></section><section class=\"entry-section\"><div class=\"section-title\">Texto inglês extraído da fotografia (OCR não canônico)</div><p class=\"entry-text\" style=\"white-space:pre-wrap\">&quot;ABpadp [Rect ‘ASp.; cf. Tdf. Proleg. p. 106] (Joseph. \n&quot;ABpayos, -ov), D128 (father of a multitude, cf. Gen. \nxvii. 5), Abraham, the renowned founder of the Jewish \nnation: Mt. i. 1 sq.; xxii. 32; Lk. xix. 9; Jn. vill. 33; \nActs iii. 25; Heb. vii. 1 sqq., andelsewhere. He is ex￾tolled by the apostle Paul as a pattern of faith, Ro. iv. 1 \nsqq. 17 sqq.; Gal. iii. 6 (cf. Heb. xi. 8), on which account \nall believers in Christ have a claim to the title sons or \nposterity of Abraham, Gal. iii. 7, 29; cf. Ro. iv. 11.</p></section><section class=\"entry-section\"><div class=\"section-title\">Fonte</div><p class=\"entry-text\">Thayer, fac-símile, página impressa 2, folha PDF 26, coluna esquerda. Em caso de diferença, prevalece a fotografia, não a transcrição OCR.</p></section></article>\n<article id=\"entry-thayer-0012\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"2\" data-thayer-pdf-leaf=\"26\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄβυσσος\" data-meanings=\"sem fundo; abismo; profundezas, morada dos mortos ou demônios\">ἄβυσσος</h1><div class=\"entry-meta\">adjetivo e substantivo feminino · Thayer, p. impressa 2, coluna esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução do artigo impresso</div><p class=\"entry-text\">ἄβυσσος, -ον: em grego clássico, adjetivo, «sem fundo, insondável», de βυσσός, relacionado a βυθός; também «ilimitado», como para riquezas ilimitadas em Ésquilo; talvez com o primeiro valor em Sabedoria 10.19. Na Escritura, ἡ ἄβυσσος, subentendendo-se χώρα, significa «a região profunda, o abismo», equivalente ao hebraico referido pelo lexicógrafo. Designa as profundezas incomensuráveis.</p>\n<p class=\"entry-text\">1. O mar profundo: Gênesis 1.2; 7.11; Deuteronômio 8.7; Eclesiástico 1.3; 16.18 e outras passagens. 2. A região dos mortos, um abismo nos níveis inferiores da terra: Salmo 70(71).21, com paralelos clássicos e patrísticos citados por Thayer (Eurípides, Phoenissae 1632; 1Clemente 20.5 e 59.3; e, em observação editorial, Atos de Tomé 32).</p>\n<p class=\"entry-text\">Como receptáculo comum dos mortos, Romanos 10.7; de maneira especial, como habitação dos demônios, Lucas 8.31; Apocalipse 9.1–2,11; 11.7; 17.8; 20.1,3. Thayer assinala que, entre os autores profanos, o emprego substantivo é encontrado em Diógenes Laércio 4(5).27; remete ainda a Knapp, Scripta varii argumenti, pp. 554 ss., e, em acréscimo editorial, a J. G. Müller sobre Fílon, p. 173 ss., e ao Bible Dictionary, verbete Deep.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Sb 10.19; Gn 1.2; 7.11; Dt 8.7; Eclo 1.3; 16.18; Sl 70(71).21; Rm 10.7; Lc 8.31; Ap 9.1–2,11; 11.7; 17.8; 20.1,3</p></section><section class=\"entry-section\"><div class=\"section-title\">Texto inglês extraído da fotografia (OCR não canônico)</div><p class=\"entry-text\" style=\"white-space:pre-wrap\">d-Burcos, in classic Greek an adj., -os, -ov, (fr. 6 Buoads \ni. q. BvOds), bottomless (so perhaps in Sap. x. 19), un￾bounded (mAovros dBuvoaos, Aeschyl. Sept. (931) 950). \nIn the Scriptures 4) d8vacos (Sept. for DIN) se. xapa, the \npit, the immeasurable depth, the abyss. Hence of ‘the \ndeep’ sea: Gen. i. 2; vii. 11; Deut. viii. 7; Sir. i. 3; \nxvi. 18, etc.; of Orcus (a very deep gulf or chasm in the \nlowest parts of the earth: Ps. lxx. (Ixxi.) 21 é€« rév aBio￾coy ths yjs, Kur. Phoen. 1632 (i605) raprapov aBvoca \nxdopara, Clem. Rom. 1 Cor. 20, 5 a8vccwr dvefiyviaora \ncriuara, ibia. 59, 3 6 éemBderav ev rais aBvocors, of God; \n[Act. Thom. 32 6 ryv aBvccoy tov taprapov oikay, of the \ndragon]), both as the common receptacle of the dead, \nRo. x. 7, and especially as the abode of demons, Lk. viii. \n31; Rev. ix. 1 sq. 11; xi. 7; xvii.8;xx.1,3. Among prof. \nauth. used as a subst. only by Diog. Laért. 4, (5,) 27 carfA￾Ges eis péXaway Tdovtéws ABvocov. Cf. Knapp, Scripta \nvar. Arg. p. 554 sq.; [J. G. Miiller, Philo’s Lehre von der \nWeltschépfung, p. 173 sq.; B. D. Am. ed. s. v. Deep].*</p></section><section class=\"entry-section\"><div class=\"section-title\">Fonte</div><p class=\"entry-text\">Thayer, fac-símile, página impressa 2, folha PDF 26, coluna esquerda. Em caso de diferença, prevalece a fotografia, não a transcrição OCR.</p></section></article>\n<article id=\"entry-thayer-0013\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"2\" data-thayer-pdf-leaf=\"26\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἅγαβος\" data-meanings=\"Ágabo, profeta cristão\">Ἅγαβος</h1><div class=\"entry-meta\">nome próprio masculino · Thayer, p. impressa 2, coluna esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução do artigo impresso</div><p class=\"entry-text\">Ἅγαβος, -ου, ὁ: Ágabo, nome de um profeta cristão, mencionado em Atos 11.28 e 21.10. Thayer assinala a discussão sobre a aspiração inicial conforme Westcott–Hort e apresenta apenas como possibilidade uma derivação da raiz hebraica «amar», sem torná-la etimologia segura.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">At 11.28; 21.10</p></section><section class=\"entry-section\"><div class=\"section-title\">Texto inglês extraído da fotografia (OCR não canônico)</div><p class=\"entry-text\" style=\"white-space:pre-wrap\">“AyaBos(on the breathing see WH. Intr. § 408], -ov, 6, \nthe name of a Christian prophet, Agabus: Acts xi. 28; \nxxi. 10. (Perhaps from 31) to love (ef. B. D. s. v.].)*</p></section><section class=\"entry-section\"><div class=\"section-title\">Fonte</div><p class=\"entry-text\">Thayer, fac-símile, página impressa 2, folha PDF 26, coluna esquerda. Em caso de diferença, prevalece a fotografia, não a transcrição OCR.</p></section></article>\n<article id=\"entry-thayer-0014\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"2\" data-thayer-pdf-leaf=\"26\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαθοεργέω\" data-meanings=\"praticar o bem; ser beneficente\">ἀγαθοεργέω</h1><div class=\"entry-meta\">verbo · Thayer, p. impressa 2, coluna esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução do artigo impresso</div><p class=\"entry-text\">ἀγαθοεργέω, -ῶ: verbo formado, segundo a análise registrada por Thayer, de ἀγαθόν e de um elemento verbal antigo não empregado isoladamente, relacionado a ἔρδω ou ἐργάζομαι. Ser beneficente, praticar o bem, sobretudo em relação aos pobres e necessitados: 1Timóteo 6.18. Compare ἀγαθουργέω. Fora desse passo, o autor registra emprego em textos eclesiásticos com o sentido «agir corretamente, proceder bem».</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">1Tm 6.18</p></section><section class=\"entry-section\"><div class=\"section-title\">Texto inglês extraído da fotografia (OCR não canônico)</div><p class=\"entry-text\" style=\"white-space:pre-wrap\">ayaboepyew, -@; (fr. the unused EPPO — equiv. to \népdo, epydfouat— and adyabdv); to be dyaboepyés, bene fi￾cent (towards the poor, the needy): 1 Tim. vi. 18 [A. V. do good}. Cf. dyafovpyé. Found besides only in ecel. \nwrit., but in the sense to do well, act rightly.*</p></section><section class=\"entry-section\"><div class=\"section-title\">Fonte</div><p class=\"entry-text\">Thayer, fac-símile, página impressa 2, folha PDF 26, coluna esquerda. Em caso de diferença, prevalece a fotografia, não a transcrição OCR.</p></section></article>\n<article id=\"entry-thayer-0015\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"2\" data-thayer-pdf-leaf=\"26\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαθοποιέω\" data-meanings=\"fazer o bem; beneficiar alguém; agir corretamente\">ἀγαθοποιέω</h1><div class=\"entry-meta\">verbo · Thayer, p. impressa 2, coluna esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução do artigo impresso</div><p class=\"entry-text\">ἀγαθοποιέω, -ῶ, com infinitivo aoristo ἀγαθοποιῆσαι: de ἀγαθοποιός. 1. Fazer o bem, realizar o que beneficia outras pessoas: Marcos 3.4, com variante textual mencionada para a expressão (Tischendorf); Lucas 6.9. Mostrar-se beneficente: Atos 14.17 segundo o texto recebido. Com referência à pessoa beneficiada, prestar favor ou fazer bem a alguém: Lucas 6.33,35; compare a construção equivalente nas passagens veterotestamentárias citadas (Sofonias 1.12; Números 10.32; Tobias 12.13 e outras).</p>\n<p class=\"entry-text\">2. Proceder bem, agir corretamente, em oposição a pecar: 1Pedro 2.15,20; 3.6,17; 3João 11. Thayer assinala a ausência quase total da palavra nos autores seculares, excetuados alguns textos tardios nos quais tem o valor astrológico de «anunciar um bom presságio».</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Mc 3.4; Lc 6.9,33,35; At 14.17 (TR); 1Pe 2.15,20; 3.6,17; 3Jo 11; Sf 1.12; Nm 10.32; Tb 12.13</p></section><section class=\"entry-section\"><div class=\"section-title\">Texto inglês extraído da fotografia (OCR não canônico)</div><p class=\"entry-text\" style=\"white-space:pre-wrap\">dyabo-rovew, &lt;3; 1 aor. inf. dyaborojoa; (fr. dyabo￾wotds); 1. to do good, do something which profits \nothers: Mk. iii. 4 [Tdf. dyadév moujoa; Lk. vi. 9]; to \nshow one’s self beneficent, Acts xiv. 17 Rec.; tud, to do some one a favor, .o benefit, Lk. vi. 33, 35, (equiv. to \n2077, Zeph. i. 12; Num. x. 32; Tob. xii. 13, etc.). 2. \nto do well, do right: 1 Pet. ii. 15, 20 (opp. to duaprdve) ; fii. 6,17; 3 Jn. 11. (Not found in secular authors, ex￾cept in a few of the later in an astrological sense, to \nfurnish a good omen.)*</p></section><section class=\"entry-section\"><div class=\"section-title\">Fonte</div><p class=\"entry-text\">Thayer, fac-símile, página impressa 2, folha PDF 26, coluna esquerda. Em caso de diferença, prevalece a fotografia, não a transcrição OCR.</p></section></article>\n<article id=\"entry-thayer-0016\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"2\" data-thayer-pdf-leaf=\"26\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαθοποιΐα\" data-meanings=\"prática do bem; conduta correta\">ἀγαθοποιΐα</h1><div class=\"entry-meta\">substantivo feminino · Thayer, p. impressa 2, coluna esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução do artigo impresso</div><p class=\"entry-text\">ἀγαθοποιΐα, -ας, ἡ (com variante ortográfica apontada por Westcott–Hort): modo de agir retamente, prática do bem. Em 1Pedro 4.19, a expressão «em fazer o bem» equivale à forma participial «agindo retamente»; Thayer compara ainda Testamento dos Doze Patriarcas, Testamento de José § 18.</p>\n<p class=\"entry-text\">O autor observa que, se for adotada a leitura alternativa de Lachmann e da margem de Tregelles, o contexto deve referir-se a atos particulares de retidão, não à conduta geral; compara Winer §27.3 e Buttmann §123.2. Na literatura eclesiástica, o substantivo designa especificamente «beneficência».</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">1Pe 4.19; Testamento de José §18</p></section><section class=\"entry-section\"><div class=\"section-title\">Texto inglês extraído da fotografia (OCR não canônico)</div><p class=\"entry-text\" style=\"white-space:pre-wrap\">Gyaborota [WH -roia (see I,¢)], -as, 9, @ course of \nright action, well-doing: év dyaborotia, 1 Pet. iv. 19 i. q. \néyaborowivres acting uprightly (cf. xii. Patr. Jos. § 18]; \nif we read here with L Tr mrg. év dyaOomouiacs we must \nunderstand it of single acts of rectitude [cf. W. § 27, 3; \nB. § 123, 2]. (In eccl. writ. dyafom. denotes bene/fi￾cence.)*</p></section><section class=\"entry-section\"><div class=\"section-title\">Fonte</div><p class=\"entry-text\">Thayer, fac-símile, página impressa 2, folha PDF 26, coluna esquerda. Em caso de diferença, prevalece a fotografia, não a transcrição OCR.</p></section></article>\n<article id=\"entry-thayer-0017\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"2\" data-thayer-pdf-leaf=\"26\" data-thayer-column=\"direita\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαθοποιός\" data-meanings=\"aquele que pratica o bem; que age corretamente\">ἀγαθοποιός</h1><div class=\"entry-meta\">adjetivo de duas terminações · Thayer, p. impressa 2, coluna direita</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução do artigo impresso</div><p class=\"entry-text\">ἀγαθοποιός, -όν: que age corretamente, que faz o bem, praticante de boas ações; 1Pedro 2.14. Thayer acrescenta referências a Eclesiástico 42.14 e Plutarco, De Iside et Osiride, §42.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">1Pe 2.14; Eclo 42.14; Plutarco, De Iside et Osiride §42</p></section><section class=\"entry-section\"><div class=\"section-title\">Texto inglês extraído da fotografia (OCR não canônico)</div><p class=\"entry-text\" style=\"white-space:pre-wrap\">dyaborovds, -dv, acting rightly, doing well: 1 Pet. ii. 14. \n[Sir. xlii. 14; Plut. de Is. et Osir. § 42.]*</p></section><section class=\"entry-section\"><div class=\"section-title\">Fonte</div><p class=\"entry-text\">Thayer, fac-símile, página impressa 2, folha PDF 26, coluna direita. Em caso de diferença, prevalece a fotografia, não a transcrição OCR.</p></section></article>\n";
